<?php
namespace Tests\Feature\Ozon;
use App\Models\Category; use App\Models\OzonAccount; use App\Models\OzonProduct; use App\Models\Product; use App\Services\Ozon\OzonProductSelectionService; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class OzonSelectionServiceTest extends TestCase { use RefreshDatabase; public function test_category_descendants_and_pivot_are_explicit_and_deduplicated(): void { $root=Category::query()->create(['name'=>'Root','slug'=>'root','status'=>'active']);$child=Category::query()->create(['name'=>'Child','slug'=>'child','status'=>'active','parent_id'=>$root->id]);$direct=Product::query()->create(['name'=>'Direct','slug'=>'direct','category_id'=>$root->id,'price'=>1]);$nested=Product::query()->create(['name'=>'Nested','slug'=>'nested','category_id'=>$child->id,'price'=>1]);$pivot=Product::query()->create(['name'=>'Pivot','slug'=>'pivot','category_id'=>$child->id,'price'=>1]);$pivot->categories()->attach($root);$service=app(OzonProductSelectionService::class);self::assertSame([$direct->id],$service->query(['category_id'=>$root->id])->pluck('id')->all());self::assertEqualsCanonicalizing([$direct->id,$nested->id,$pivot->id],$service->query(['category_id'=>$root->id,'include_descendants'=>true,'include_additional_categories'=>true])->pluck('id')->all()); }
 public function test_existing_link_is_excluded_only_for_selected_account(): void { $cat=Category::query()->create(['name'=>'Root','slug'=>'root','status'=>'active']);$p=Product::query()->create(['name'=>'P','slug'=>'p','sku'=>'P','category_id'=>$cat->id,'price'=>1]);$a=OzonAccount::factory()->create();$b=OzonAccount::factory()->create();OzonProduct::factory()->create(['ozon_account_id'=>$a->id,'product_id'=>$p->id,'offer_id'=>'P']);$service=app(OzonProductSelectionService::class);self::assertCount(0,$service->query(['category_id'=>$cat->id,'not_added'=>true,'ozon_account_id'=>$a->id])->get());self::assertCount(1,$service->query(['category_id'=>$cat->id,'not_added'=>true,'ozon_account_id'=>$b->id])->get()); } }
